import{_ as o,l as i,o as e,c as C,v as r,p as n,x as t,d as A,i as s,S as c}from"./chunks/framework.InCnrqk-.js";const D=JSON.parse('{"title":"资本成本与 WACC","description":"","frontmatter":{"title":"资本成本与 WACC","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/wacc-cost-of-capital.md","filePath":"econ/wacc-cost-of-capital.md","lastUpdated":1789023840000}'),p={name:"econ/wacc-cost-of-capital.md"};function _(d,a,E,h,m,W){const l=i("Mermaid");return e(),C("div",null,[a[1]||(a[1]=r('<h1 id="资本成本与-wacc" tabindex="-1">资本成本与 WACC <a class="header-anchor" href="#资本成本与-wacc" aria-label="Permalink to &quot;资本成本与 WACC&quot;">​</a></h1><div class="epigraph"><p>加权平均资本成本不是「债务便宜所以应当多借」的许可证；它是在既定资本结构下，把税后经营现金流折成资产价值的一个利率。</p><footer>—— 据 Modigliani and Miller, AER 1958/1963；Miles and Ezzell, Journal of Financial and Quantitative Analysis 1980；Brealey, Myers and Allen 整理</footer></div><p><a href="/econ/npv-irr-pitfalls">上一课</a>把接受规则钉成 NPV，贴现率 \\(r\\) 仍是占位符。本课缺口是把 \\(r\\) 写成加权平均资本成本（WACC）：在税盾已经进入<a href="/econ/mm-corporate-tax">1963</a>、权衡给出目标切片之后，如何把 \\(r_E\\) 与 \\(r_D\\) 合成一个对自由现金流的折现率。不重做家庭自制杠杆，不把项目 beta 提前。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><a href="/econ/modigliani-miller">MM 1958</a> 已经警告：看到 \\(r_E\\gt r_D\\) 就加杠杆，是把切片成本当成资产成本。有公司税之后，税后债务成本是 \\(r_D(1-\\tau_c)\\)，教科书 WACC 写成</p> \\[r_{\\mathrm{WACC}}=\\frac{E}{V}r_E+\\frac{D}{V}r_D(1-\\tau_c). \\]<p>若每期按市值权重保持 \\(D/V\\) 不变，用这个利率去折未杠杆自由现金流，得到的是杠杆企业价值 \\(V_L\\)——税盾被折进贴现率，而不是加在现金流上。缺口是许可证：权重用目标结构还是现行结构？现金流必须是对全部资本提供者的税后经营现金流，不能再扣利息。上一课的 IRR 门槛若换成 WACC，陷阱一个不少。</p><p><span class="marginnote">Miles–Ezzell（1980）：若杠杆按价值比例调整，税盾的折现率不是 \\(r_D\\)，第一期之后更接近 \\(r_U\\)。MM 的 \\(\\tau_c D\\) 对应债务水平固定的永久债。公式要与再平衡政策匹配，不能混用。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>三块输入：\\(r_E\\) 来自股权要求回报（下一课用项目或可比的 CAPM 来填），\\(r_D\\) 来自债务承诺收益或到期收益率（违约风险高时要用期望收益，不是承诺收益），权重 \\(E/V\\)、\\(D/V\\) 用<strong>目标</strong>市值结构，不是账面、也不是「为了让项目过关而假设的全债」。\\(V=E+D\\) 是企业价值，不是资产账面。</p><p>现金流口径：WACC 折的是对债与股都自由的现金流（FCFF）——税按<strong>假如无杠杆</strong>来算经营税，利息税盾留给 \\((1-\\tau_c)\\) 因子。若把税后利息再扣一次，税盾被算两遍。股权自由现金流必须用 \\(r_E\\) 折，不能用 WACC。</p>',11)),(e(),n(c,null,{default:t(()=>[s(l,{id:"mermaid-29",class:"mermaid",graph:"flowchart%20TD%0A%20%20RA%5B%22%E8%B5%84%E4%BA%A7%E9%A3%8E%E9%99%A9%20rA%20%E6%88%96%20rU%22%5D%20--%3E%20WACC%5B%22rWACC%22%5D%0A%20%20RE%5B%22%E8%82%A1%E6%9D%83%20rE%22%5D%20--%3E%20WACC%0A%20%20RD%5B%22%E5%80%BA%E5%8A%A1%20rD%22%5D%20--%3E%20WACC%0A%20%20TAX%5B%22%E7%A8%8E%E7%9B%BE%3A%201-Tc%22%5D%20--%3E%20WACC%0A%20%20WACC%20--%3E%20FCFF%5B%22%E6%8A%98%E6%9C%AA%E6%9D%A0%E6%9D%86%20FCF%22%5D%0A%20%20FCFF%20--%3E%20VL%5B%22VL%20%E5%B7%B2%E5%90%AB%E7%A8%8E%E7%9B%BE%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[A(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<p>Miles–Ezzell 与 Harris–Pringle 给出不同再平衡假设下税盾的折现。教学上：目标 \\(D/V\\) 稳定，用教科书 WACC；债务金额锁定（LBO、项目融资有还本表），不要用常数 WACC，下一课 <a href="/econ/apv">APV</a> 把税盾单独加。Brealey–Myers 的操作句是：先想清楚债务怎么走，再选公式。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>机制是把税后要求回报写成对同一资产的加权。无税时 WACC 退回 \\(r_A\\)，与切片无关。有税且按价值再平衡时，多借债降低 WACC，下降来自 \\(\\tau_c\\)，不是来自「银行贷款利率看起来低」。\\(r_E\\) 仍随杠杆上升（命题 II）；权重里债务变大、股权变贵，两边一起动。把现行低 \\(r_D\\) 塞进一个高杠杆权重、却用今天尚未加杠杆的 \\(r_E\\)，会系统低估 WACC、高估 NPV。</p><p>与权衡的衔接：目标 \\(D/V\\) 来自税盾对困境成本，不是来自「把 WACC 压到最低」。若把 WACC 当目标函数去加杠杆，会忽略困境对现金流本身的破坏——那些破坏应进 FCF 或进 APV 的副作用，不能靠再压贴现率来假装没有。</p><h3 id="承诺收益不是期望收益" tabindex="-1">承诺收益不是期望收益 <a class="header-anchor" href="#承诺收益不是期望收益" aria-label="Permalink to &quot;承诺收益不是期望收益&quot;">​</a></h3><p>高收益债的到期收益率含违约补偿。折现期望现金流若用承诺 \\(r_D\\)，分母偏大。WACC 里的 \\(r_D\\) 应是债权人的期望回报，接近评级相近的债务期望收益，而不是把垃圾债 YTM 直接当成本。Brealey–Myers 把这写成常见高估债务成本、从而高估 WACC 的反向错误；更常见的实务错误仍是低估。</p><p><span class="marginnote">循环：WACC 需要 \\(E/V\\)，而 \\(V\\) 正是折现结果。迭代到权重与价值一致，或用 APV 躲开循环。目标结构已知时，用目标权重，循环较轻。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不要把 WACC 当成与资本结构无关的「公司折现率」去折所有项目：项目风险不同于公司资产风险时，下一课改 beta，不改成「公司 WACC 一刀切」。也不要把部门要求回报写成谈判政治——那是配额，上一课已经禁止用错误比率替代 NPV。</p><p>本课不推导 CAPM，不估计市场溢价。\\(r_E\\) 在这里仍是输入。<a href="/econ/pecking-order">优序</a>说发股有柠檬，那是发行成本，不是把 WACC 里的 \\(r_E\\) 人为加几个点当「股权贵」。柠檬应进发行折价或 APV 副作用。</p><p>后课默认：WACC 折未杠杆 FCF、权重用目标市值、税盾与再平衡政策匹配。债务水平锁定则离开常数 WACC，交给 APV。不要用 \\(r_E\\gt r_D\\) 证明应当加杠杆。</p><p>宏观课序与家庭欧拉给出的是随机折现；WACC 是确定等价或 beta 调整后的一个利率，不是另一套偏好。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>WACC 是既定（目标）结构下对 FCFF 的折现率；税后债务成本不证明「应当多借」。</li><li>权重用市值目标；现金流不要再扣利息；再平衡政策决定能否用常数 WACC。</li><li>下一课用 CAPM 填项目的 \\(r_E\\) 或 \\(r_U\\)，而不是公司现成的一个数。</li><li>出处：MM 1958/1963；Miles and Ezzell, <em>JFQA</em> 1980；Brealey, Myers and Allen。</li></ul>',14))])}const u=o(p,[["render",_]]);export{D as __pageData,u as default};
